import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class UnknownNetworkException extends BaseException {
    constructor() {
        super(
            'Network.UnknownNetworkError',
            'We could not process your request, please try again.'
        );
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericNetworkErrorMessage(locale);
    }
}
